// The scheduler's GitHub WRITES — the small set of issue mutations both dispatch
// mechanisms make, over the injected `gh` reader from signals/gh.mjs. Reads live
// with their callers; these are here so the slot machinery and the work-item queue
// share one implementation of each, rather than two that drift.
//
// LABEL WRITES ARE GRANULAR, ALWAYS (tasks-dispatch DESIGN §4, RESEARCH §2): add
// and remove NAMED labels (POST/DELETE), never write the label SET (PUT). A
// set-write replaces from a stale snapshot and clobbers concurrent transitions —
// a bug class GitHub's own CLI shipped (cli/cli#4861) — and with a scheduler run and
// several executors all moving labels at once, that is a correctness rule rather
// than a style preference.

// Ensure every label exists before any is applied. Load-bearing, not cosmetic:
// GitHub does not create a label when you apply one (the issues API 422s on an
// unknown label), so the thing that assigns a label must guarantee it first.
// Idempotent (201 created / 422 already exists are both success) and self-healing
// — a deleted label reappears on the next run.
export async function ensureLabels(gh, repo, labels) {
  for (const { name, color, description } of labels) {
    const res = await gh(`/repos/${repo}/labels`, { method: 'POST', body: { name, color, description } });
    if (res.status === 201) continue;                       // created to spec — nothing further
    if (res.status === 422) {
      // The NAME is taken; that says nothing about the colour or description. A
      // label GitHub auto-created (applying an unknown name to an issue mints it
      // grey `ededed`, no description) would keep those defaults for good, because
      // POST 422s forever. So reconcile the shape, not just the existence — that
      // is what makes the self-healing claim above true for drift and not only for
      // deletion. PATCH is idempotent: an already-correct label is a no-op write.
      const fix = await gh(`/repos/${repo}/labels/${encodeURIComponent(name)}`, {
        method: 'PATCH', body: { color, description },
      });
      if (fix.status !== 200) console.log(`! could not reconcile label "${name}": ${fix.status}`);
      continue;
    }
    console.log(`! could not ensure label "${name}": ${res.status}`);
  }
}

export const addLabel = (gh, repo, number, name) =>
  gh(`/repos/${repo}/issues/${number}/labels`, { method: 'POST', body: { labels: [name] } });

// A label that is already absent 404s; that is the desired end state, so it is
// success. Nothing here reads the response beyond reporting it.
export const removeLabel = (gh, repo, number, name) =>
  gh(`/repos/${repo}/issues/${number}/labels/${encodeURIComponent(name)}`, { method: 'DELETE' });

// The swap every state transition makes. Remove-then-add, and NOT atomic —
// GitHub has no atomic label swap. That is safe because labels are visibility and
// the pick filter, never the arbiter (the claim comments are); what a torn swap
// CAN leave is an open item wearing no state label at all, which the janitor
// repairs (tasks-dispatch DESIGN §6.2, §11).
export async function swapLabel(gh, repo, number, from, to) {
  await removeLabel(gh, repo, number, from);
  return addLabel(gh, repo, number, to);
}

export const comment = (gh, repo, number, body) =>
  gh(`/repos/${repo}/issues/${number}/comments`, { method: 'POST', body: { body } });

// The ONE sanctioned edit to a comment, and the reason the arbitration record is
// no longer strictly append-only: an executor striking its OWN claim on the way
// out (tasks-dispatch DESIGN §6.2). Only a claim's author ever edits it, so a
// claim can be withdrawn but never forged earlier, and comment ids still give the
// total order arbitration reads.
export const editComment = (gh, repo, commentId, body) =>
  gh(`/repos/${repo}/issues/comments/${commentId}`, { method: 'PATCH', body: { body } });

export const listComments = async (gh, repo, number) => {
  const out = [];
  for (let page = 1; ; page += 1) {
    const { status, json } = await gh(`/repos/${repo}/issues/${number}/comments?per_page=100&page=${page}`);
    if (status !== 200 || !Array.isArray(json) || json.length === 0) break;
    out.push(...json);
    if (json.length < 100) break;
  }
  return out;
};

export const closeIssue = (gh, repo, number, stateReason = 'completed') =>
  gh(`/repos/${repo}/issues/${number}`, { method: 'PATCH', body: { state: 'closed', state_reason: stateReason } });

export async function createIssue(gh, repo, { title, body, labels = [] }) {
  const { status, json } = await gh(`/repos/${repo}/issues`, { method: 'POST', body: { title, body, labels } });
  // The STATUS is read, not just the body (#the-fleet-froze-on-this): a 403 from a
  // repo whose Actions cannot create issues puts an error object where the issue
  // should be, and a body-only destructure turns that refusal into a plausible
  // object whose `.number` is simply undefined.
  return { status, number: status >= 200 && status < 300 ? json?.number ?? null : null, json };
}

// The one write here that is not an issue mutation: fire a `workflow_dispatch`.
// It is how the queue CHAINS (DESIGN §10) — a run that settled its item starts a
// fresh one rather than leaving the remainder for the cron — and `workflow_dispatch`
// is one of the two events the default `GITHUB_TOKEN` may fire, the explicit
// exemption in the same recursion guard that suppresses its label events, so no
// wider credential is involved.
//
// Judged by STATUS, never by the body: a token without `actions: write` 403s this
// POST with a plausible JSON body, and a body-only check would log it as sent.
export async function dispatchWorkflow(gh, repo, file, ref) {
  const { status } = await gh(`/repos/${repo}/actions/workflows/${file}/dispatches`, {
    method: 'POST', body: { ref },
  });
  return { ok: status === 204, status };
}

export const readIssue = async (gh, repo, number) => {
  const { status, json } = await gh(`/repos/${repo}/issues/${number}`);
  return status === 200 ? json : null;
};

content.content:
// APPLYING a status transition — the write half of the vocabulary whose read half
// is `work-item.mjs`'s decode (tasks-dispatch DESIGN §4, the migration of #1119).
//
// One rule, and it is why this is not a plain `swapLabel`: the item may wear ANY
// engine version's spelling of the status it is leaving. A member's items outlive
// its converges, so an item filed as `task:ready` is picked up by an engine that
// writes `task:status:waiting-for-executor`, and a swap that named one spelling
// would leave the other standing — an item wearing two live statuses, which is the
// torn state the janitor exists to repair.
//
// Writes stay granular (add and remove named labels, never a set-write): with
// several executors and a scheduler run moving labels at once, a set-write from a
// stale snapshot clobbers a concurrent transition (DESIGN §4).
// The removes are UNCONDITIONAL — every spelling of the status being left, not
// only the ones the caller's snapshot shows. A caller holds the labels it read
// before its own earlier transitions, so filtering on that snapshot would skip
// exactly the label this engine just wrote; removing a label an issue does not
// carry 404s, which is the end state asked for and therefore success.
import { spellingsOf } from './work-item.mjs';

// Move `item` out of `fromStatus` (canonical — every spelling of it goes) and into
// the label `to`, which is whatever spelling this engine writes.
export async function swapStatus(api, gh, repo, item, fromStatus, to) {
  await clearStatus(api, gh, repo, item, fromStatus);
  return api.addLabel(gh, repo, item.number, to);
}

// Leave a status without entering another — the close path, where the terminal
// label is applied separately.
export async function clearStatus(api, gh, repo, item, status) {
  for (const label of spellingsOf(status)) {
    await api.removeLabel(gh, repo, item.number, label);
  }
}
=== readiness.mjs (readyDependents) ===
// WHEN A BLOCKED ITEM MAY RUN, and who releases it (tasks-dispatch DESIGN §9,
// decision §15.19). Two callers ask the same question at different moments: the
// scheduler run, hourly, over every open item; and whoever CLOSES an item, immediately,
// over the dependents that item was holding. The predicate lives here so those
// two can never answer it differently — the failure that shape produces is a
// chain link that waits an hour on one path and runs at once on the other, with
// nothing red to say which is right.
//
// The scheduler run stays the backstop, deliberately: a close performed by a HUMAN (or by
// a session that stopped early) runs none of this, and the hourly pass is what
// makes that harmless rather than a chain that never resumes.

import { BLOCKED, READY, STATUS_BLOCKED, isStatus, parseWorkItemBody } from './work-item.mjs';
import { swapStatus } from './apply-status.mjs';

// Is this item's wait over? `stateOf(n)` answers the state of a `Blocked-by`
// target that may not be a work item at all — an unknown number is never treated
// as closed, so an unreadable blocker DELAYS rather than releases (the
// convergence-not-prevention posture). An item in triage is nobody's to release.
export function isReleasable(item, { stateOf = () => null, nowMs = Date.now() } = {}) {
  if (item.state !== 'open' || !isStatus(item, STATUS_BLOCKED)) return false;
  const { notBefore, blockedBy } = parseWorkItemBody(item.body);
  const blockersDone = blockedBy.every((n) => stateOf(n) === 'closed');
  const timeReached = notBefore === null || nowMs >= new Date(notBefore).getTime();
  return blockersDone && timeReached;
}

// Which open items were waiting on THIS one, and are now free. Scoped to items
// naming `closedIssue` among their blockers: a close is not a general readiness
// sweep, and treating it as one would have every close re-derive the whole scheduler run.
export function releasedBy(closedIssue, open = [], { stateOf = () => null, nowMs = Date.now() } = {}) {
  const dependsOnIt = (i) => parseWorkItemBody(i.body).blockedBy.includes(closedIssue);
  return open.filter((i) => dependsOnIt(i) && isReleasable(i, { stateOf, nowMs }));
}

// The shell: read the queue, release what this close freed, and say so. Returns
// the numbers readied, so the caller can decide whether the chain needs a run —
// this function starts none itself, because the executor's own drain (§10)
// already re-reads the queue after every settle and covers exactly this.
//
// The blocker states come from the issue endpoint one at a time, and only for the
// candidates' own `Blocked-by` numbers: a dependent typically names one or two,
// and reading them beats fetching the repo's issue list a second time.
export async function readyDependents(api, gh, repo, closedIssue, {
  open = null, now = () => new Date(), log = () => {},
} = {}) {
  // Read the queue HERE rather than take the caller's copy: a run holds its item
  // for as long as the work takes, and what was blocked when it started is not
  // what is blocked when it closes.
  if (!open) ({ listOpenWorkItems: open } = await import('./read.mjs'), open = await open(gh, repo));
  const wanted = new Set();
  for (const i of open) {
    if (parseWorkItemBody(i.body).blockedBy.includes(closedIssue)) {
      for (const n of parseWorkItemBody(i.body).blockedBy) wanted.add(n);
    }
  }
  if (!wanted.size) return [];
  const states = new Map([[closedIssue, 'closed']]);
  for (const n of wanted) {
    if (states.has(n)) continue;
    const issue = await api.readIssue(gh, repo, n);
    states.set(n, issue?.state ?? null);
  }

  const freed = releasedBy(closedIssue, open, {
    stateOf: (n) => states.get(n) ?? null,
    nowMs: now().getTime(),
  });
  for (const item of freed) {
    await swapStatus(api, gh, repo, item, STATUS_BLOCKED, READY);
    await api.comment(gh, repo, item.number,
      `Released: #${closedIssue} has closed, and nothing else holds this item.`);
    log(`- #${item.number}: readied — #${closedIssue} closed and nothing else holds it`);
  }
  return freed.map((i) => i.number);
}

